// Group HeartRate samples by date and compute min / max / avg

const daily = {};

for (const item of items) {
  const record = item.json;
  if (!Array.isArray(record.samples)) continue;

  for (const s of record.samples) {
    const bpm = s.beatsPerMinute;
    if (typeof bpm !== 'number') continue;

    const date = new Date(s.time).toISOString().split('T')[0];

    if (!daily[date]) {
      daily[date] = {
        sum: 0,
        count: 0,
        min: bpm,
        max: bpm
      };
    }

    daily[date].sum += bpm;
    daily[date].count += 1;
    daily[date].min = Math.min(daily[date].min, bpm);
    daily[date].max = Math.max(daily[date].max, bpm);
  }
}

const output = [];

for (const [date, d] of Object.entries(daily)) {
  output.push({
    json: {
      Date: date,
      BpmMin: d.min,
      BpmMax: d.max,
      BpmAvg: Math.round(d.sum / d.count)
    }
  });
}

return output;

