// Aggregates sleep per WAKE-UP DATE (fixes missing 17th)

const STAGE_MAP = {
  1: 'AWAKE',
  4: 'LIGHT',
  5: 'DEEP',
  6: 'REM'
};

const dayMap = {};

// ---- FIRST PASS: group by wake-up date ----
for (const item of items) {
  const input = item.json;

  if (!Array.isArray(input.stages)) continue;

  for (const s of input.stages) {
    const stageName = STAGE_MAP[s.stage];
    if (!stageName) continue;

    const start = new Date(s.startTime);
    const end = new Date(s.endTime);
    if (isNaN(start) || isNaN(end)) continue;

    const duration = (end - start) / 60000;
    if (duration <= 0) continue;

    // ✅ USE endTime date (wake-up day)
    const date = end.toISOString().split('T')[0];

    if (!dayMap[date]) {
      dayMap[date] = {
        date,
        total_sleep_minutes: 0,
        light_minutes: 0,
        deep_minutes: 0,
        rem_minutes: 0,
        awake_minutes: 0
      };
    }

    const day = dayMap[date];

    switch (stageName) {
      case 'LIGHT':
        day.light_minutes += duration;
        day.total_sleep_minutes += duration;
        break;

      case 'DEEP':
        day.deep_minutes += duration;
        day.total_sleep_minutes += duration;
        break;

      case 'REM':
        day.rem_minutes += duration;
        day.total_sleep_minutes += duration;
        break;

      case 'AWAKE':
        day.awake_minutes += duration;
        break;
    }
  }
}

// ---- SECOND PASS: round + output ----
const output = Object.values(dayMap)
  .sort((a, b) => a.date.localeCompare(b.date))
  .map(d => ({
    json: {
      date: d.date,
      total_sleep_minutes: Math.round(d.total_sleep_minutes),
      light_minutes: Math.round(d.light_minutes),
      deep_minutes: Math.round(d.deep_minutes),
      rem_minutes: Math.round(d.rem_minutes),
      awake_minutes: Math.round(d.awake_minutes)
    }
  }));

return output;

const combined = items
  .map(item => item.json.error)
  .filter(Boolean)
  .join("\n");

return [{
  json: {
    error: combined
  }
}];

