const out = {};

for (const item of items) {
  const key = Object.keys(item.json)[0];
  out[key] = item.json[key];
}

return [{ json: out }];

const items = $input.all();

// Merge metrics + AI summary safely
const metrics = items.find(i => i.json.weekly_health_score)?.json || {};
const ai = items.find(i => i.json.ai_summary)?.json || {};

const report = { ...metrics, ...ai };

// Helpers
const tableRows = (arr, cols) =>
  (arr || []).map(r =>
    `<tr>${cols.map(c => `<td>${r[c] ?? '—'}</td>`).join('')}</tr>`
  ).join('');

const avg = (arr, key) =>
  arr && arr.length
    ? Math.round(arr.reduce((a,b) => a + b[key], 0) / arr.length)
    : '—';

// HTML
const html = `
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<style>
body { font-family: Inter, Arial, sans-serif; margin: 40px; color: #1f2937; }
h1, h2 { color: #111827; }
.cover { page-break-after: always; }

.kpis { display: flex; gap: 24px; margin: 20px 0; }
.kpi { padding: 16px; border-radius: 12px; background: #f3f4f6; width: 220px; }
.kpi-value { font-size: 32px; font-weight: bold; }

.section {
  page-break-inside: avoid;
  break-inside: avoid;
  margin-bottom: 40px;
}

.page-break {
  page-break-after: always;
  break-after: page;
}

table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 12px;
}
th, td {
  border-bottom: 1px solid #e5e7eb;
  padding: 8px;
  text-align: left;
}
th { background: #f9fafb; }

.ai-box {
  background: #eef2ff;
  padding: 20px;
  border-radius: 12px;
  margin-top: 24px;
}

.muted { color: #6b7280; }
</style>
</head>

<body>

<!-- COVER PAGE -->
<div class="cover">
  <h1>Weekly Health Report</h1>

  <div class="kpis">
    <div class="kpi">
      <div class="muted">Health Score</div>
      <div class="kpi-value">${report.weekly_health_score ?? '—'}</div>
    </div>

    <div class="kpi">
      <div class="muted">Weekend Recovery Bonus</div>
      <div class="kpi-value">${report.weekend_recovery_bonus ?? '—'}</div>
    </div>

    <div class="kpi">
      <div class="muted">Avg Sleep Efficiency</div>
      <div class="kpi-value">${avg(report.Sleep_Eff, 'sleep_efficiency_pct')}%</div>
    </div>
  </div>

  <div class="ai-box">
    <h2>AI Summary</h2>
    <p>${(report.ai_summary || 'No summary available').replace(/\n/g,'<br>')}</p>
  </div>
</div>

<!-- PAGE 2 -->
<div class="section">
  <h2>Sleep Efficiency</h2>
  <table>
    <tr><th>Day</th><th>Date</th><th>Efficiency (%)</th></tr>
    ${tableRows(report.Sleep_Eff, ['Day','Date','sleep_efficiency_pct'])}
  </table>
</div>

<div class="section">
  <h2>Total Sleep (minutes)</h2>
  <table>
    <tr><th>Day</th><th>Date</th><th>Total Sleep</th></tr>
    ${tableRows(report.Total_Sleep, ['Day','Date','TotalSleep'])}
  </table>
</div>

<div class="page-break"></div>

<!-- PAGE 3 -->
<div class="section">
  <h2>Step Count</h2>
  <table>
    <tr><th>Day</th><th>Date</th><th>Steps</th></tr>
    ${tableRows(report.Step_Count, ['Day','Date','StepCount'])}
  </table>
</div>

<div class="section">
  <h2>Oxygen Saturation</h2>
  <table>
    <tr><th>Day</th><th>Date</th><th>Oxygen (%)</th></tr>
    ${tableRows(report.Oxygen, ['Day','Date','Oxygen'])}
  </table>
</div>

<div class="page-break"></div>

<!-- PAGE 4 -->
<div class="section">
  <h2>Heart Rate</h2>
  <table>
    <tr><th>Day</th><th>Date</th><th>Avg</th><th>Min</th><th>Max</th></tr>
    ${(report.Avg_BPM || []).map((r,i) => `
      <tr>
        <td>${r.Day}</td>
        <td>${r.Date}</td>
        <td>${r.BpmAVG}</td>
        <td>${report.Min_BPM?.[i]?.BpmMIN ?? '—'}</td>
        <td>${report.Max_BPM?.[i]?.BpmMAX ?? '—'}</td>
      </tr>
    `).join('')}
  </table>
</div>

</body>
</html>
`;

return [{ html }];

const combined = {};

for (const item of items) {
  // each item.json is either a metric object or { ai_summary: "..." }
  Object.assign(combined, item.json);
}

return [
  {
    json: combined
  }
];
